const pinLegacyDocumentFinalizationIntentVersions = `-- name: PinLegacyDocumentFinalizationIntentVersions :one
UPDATE document_finalization_intents
SET final_pdf_version_id = $1,
    audit_cert_version_id = $2,
    audit_payload_version_id = $3,
    audit_signature_version_id = $4,
    evidence_version_pins_required = TRUE,
    updated_at = now()
WHERE document_id = $5
  AND org_id = $6
  AND evidence_version_pins_required = FALSE
  AND final_pdf_version_id IS NULL
  AND audit_cert_version_id IS NULL
  AND audit_payload_version_id IS NULL
  AND audit_signature_version_id IS NULL
RETURNING document_id, org_id, mode, final_pdf_key, final_pdf_sha256, audit_cert_key, audit_cert_sha256, audit_payload_key, audit_payload_sha256, audit_signature_key, audit_signature_sha256, retention_started_at, retention_completed_at, attempts, last_error, created_at, updated_at, final_pdf_version_id, audit_cert_version_id, audit_payload_version_id, audit_signature_version_id, evidence_version_pins_required, completion_effective_at, retain_until
`

type PinLegacyDocumentFinalizationIntentVersionsParams struct {
	FinalPdfVersionID       pgtype.Text `json:"final_pdf_version_id"`
	AuditCertVersionID      pgtype.Text `json:"audit_cert_version_id"`
	AuditPayloadVersionID   pgtype.Text `json:"audit_payload_version_id"`
	AuditSignatureVersionID pgtype.Text `json:"audit_signature_version_id"`
	DocumentID              uuid.UUID   `json:"document_id"`
	OrgID                   uuid.UUID   `json:"org_id"`
}

// Existing finalizing rows from before migration 47 have digest commitments but
// no VersionIds. Resolve each once, persist all four atomically, then every
// verify/retain/publish retry becomes exact-version only.
func (q *Queries) PinLegacyDocumentFinalizationIntentVersions(ctx context.Context, arg PinLegacyDocumentFinalizationIntentVersionsParams) (*DocumentFinalizationIntent, error) {
	row := q.db.QueryRow(ctx, pinLegacyDocumentFinalizationIntentVersions,
		arg.FinalPdfVersionID,
		arg.AuditCertVersionID,
		arg.AuditPayloadVersionID,
		arg.AuditSignatureVersionID,
		arg.DocumentID,
		arg.OrgID,
	)
	var i DocumentFinalizationIntent
	err := row.Scan(
		&i.DocumentID,
		&i.OrgID,
		&i.Mode,
		&i.FinalPdfKey,
		&i.FinalPdfSha256,
		&i.AuditCertKey,
		&i.AuditCertSha256,
		&i.AuditPayloadKey,
		&i.AuditPayloadSha256,
		&i.AuditSignatureKey,
		&i.AuditSignatureSha256,
		&i.RetentionStartedAt,
		&i.RetentionCompletedAt,
		&i.Attempts,
		&i.LastError,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.FinalPdfVersionID,
		&i.AuditCertVersionID,
		&i.AuditPayloadVersionID,
		&i.AuditSignatureVersionID,
		&i.EvidenceVersionPinsRequired,
		&i.CompletionEffectiveAt,
		&i.RetainUntil,
	)
	return &i, err
}
